// Helper hit counter for the slv domain (not printed by the final block)
int unsigned hits_slv_CHK_001 = 0;

// Combinational conditions (parameter dependent)
wire chk001_slv_ok = (PARA_APBCDC_APB5 == 0) ?
                     ((o_apb_pwakeup == 1'b0) && (o_apb_pauser == '0) && (o_apb_pwuser == '0)) :
                     (((PARA_APBCDC_USER_REQ_W  != 0) || (o_apb_pauser == '0)) &&
                      ((PARA_APBCDC_USER_DATA_W != 0) || (o_apb_pwuser == '0)));

wire chk001_mst_ok = (PARA_APBCDC_APB5 == 0) ?
                     ((o_apb_pruser == '0) && (o_apb_pbuser == '0)) :
                     (((PARA_APBCDC_USER_DATA_W != 0) || (o_apb_pruser == '0)) &&
                      ((PARA_APBCDC_USER_RESP_W != 0) || (o_apb_pbuser == '0)));

// CHK-001: Absent APB5 signals drive zero, mst domain (AB2-3-45, AB2-20.2-08, AB2-3-44, AB2-8-04, AB2-8-05, AB2-8-06, AB2-8-08)
a_CHK_001: assert property (@(posedge i_clk_mst) disable iff (!i_rst_n_mst) 1'b1 |-> chk001_mst_ok)
  else begin fails_CHK_001++; $display("NNC_FAIL CHK-001 @%0t", $time); end
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (1'b1)) hits_CHK_001 <= hits_CHK_001 + 1;

// CHK-001: Absent APB5 signals drive zero, slv domain (AB2-3-45, AB2-20.2-08, AB2-3-44, AB2-8-04, AB2-8-05, AB2-8-06, AB2-8-08)
a_CHK_001_slv: assert property (@(posedge i_clk_slv) disable iff (!i_rst_n_slv) 1'b1 |-> chk001_slv_ok)
  else begin fails_CHK_001++; $display("NNC_FAIL CHK-001 @%0t", $time); end
always_ff @(posedge i_clk_slv) if (!(!i_rst_n_slv) && (1'b1)) hits_slv_CHK_001 <= hits_slv_CHK_001 + 1;
